CommonData.PCCustomCSS:
/* ============================================================================
   BARRIEREFREIHEITS-ANPASSUNGEN FÜR ONETRUST COOKIE-BANNER
============================================================================ */

/* 1 & 7. Fokus-Outline sichtbar und farblich klar */
.ot-sdk .ot-btn:focus,
.ot-sdk .ot-toggle:focus,
.ot-sdk .ot-b-addl-desc:focus {
  outline: 3px solid #005A9C !important; /* Dunkelblauer Fokusrahmen */
  outline-offset: 2px;
}

/* 2. Buttons mit klarerem Hover- und Fokuszustand */
.ot-sdk .ot-btn:hover,
.ot-sdk .ot-btn:focus,
.ot-sdk .ot-b-addl-desc:hover,
.ot-sdk .ot-b-addl-desc:focus {
  background-color: #004A95 !important;  /* Etwas dunkleres Blau */
  text-decoration: underline !important; /* Visuelle Rückmeldung */
  opacity: 0.95;
}

/* 3 & 10. Deutliche Unterscheidung Toggle AN/AUS */
.ot-sdk .ot-toggle {
  background-color: #CCCCCC !important; /* AUS-Zustand: Hellgrau */
}
.ot-sdk .ot-toggle.ot-toggle-on {
  background-color: #0078D4 !important; /* AN-Zustand: kräftiges Blau */
}

/* 10 (optional): Symbol im aktiven Toggle */
.ot-sdk .ot-toggle.ot-toggle-on .ot-toggle-handle::after {
  content: '✔';
  color: white;
  position: absolute;
  right: 6px;
  top: 3px;
  font-size: 10px;
}

/* 4. "Cookie-Details"-Buttons visuell hervorheben */
.ot-sdk .ot-b-addl-desc:hover,
.ot-sdk .ot-b-addl-desc:focus {
  background-color: #004A95 !important;
  color: #FFFFFF !important;
  text-decoration: underline !important;
}

/* 5 & 11. Platzhaltertexte lesbar gestalten */
.ot-sdk ::placeholder {
  color: #333333 !important;    /* Deutlich dunklerer Grauton */
  opacity: 1 !important;
}

/* 6. Chevron-Icons für Screenreader verstecken (geht nur per JS ) */

/* 8. Visueller Hover-Indikator für Toggles */
.ot-sdk .ot-toggle:hover .ot-toggle-handle {
  box-shadow: 0 0 3px 2px rgba(0, 0, 0, 0.3) !important;
}

/* Optional: Akkordeon-Hintergrund mit mehr Kontrast */
.ot-sdk .ot-accordion-layout {
  background-color: #D6D6D6 !important;
}
